                    sum = sum + error;
                } else {
                    error = (estimator.getEstimate(the_key) - realCounts.get(the_key));
                    if (error > max_error)
                        max_error = error;
                    sum = sum + error;
                }
            }
            Assert.assertTrue(max_error <= 2 * n * error_tolerance);
        }
    }
}

