    // then it should also be expected to change.
    expectedMem.putInt(49, HashUtils.pairOfKeyAndVal(892, (byte) 10));
    fields.intoByteArray(stored, 0);
    Assert.assertEquals(stored, expected);
    boolean exceptionThrown = false;
    try {
