@Test
public void checkCopySmall() {
    int memCapacity = 64;
    int half = memCapacity / 2;
    NativeMemory mem = new AllocMemory(memCapacity);
    Memory region = new MemoryRegion(mem, 0, memCapacity);
    region.clear();
    for (int i = 0; i < half; i++) {
        region.putByte(i, (byte) i);
