    assertFalse(usk.isCompact());
    assertFalse(usk.isOrdered());
    for (int i = 0; i < u; i++) usk.update(i);
    //forces size back to k
    sk1.rebuild();
    //get baseline values
    double uskEst = usk.getEstimate();
    double uskLB = usk.getLowerBound(2);
    double uskUB = usk.getUpperBound(2);
