@Test
public void checkPrimitiveUpdates() {
    int k = 32;
    Memory uMem = new NativeMemory(new byte[getMaxUnionBytes(k)]);
    Union union = SetOperation.builder().initMemory(uMem).buildUnion(k);
    union.update(1L);
    //#1 double
    union.update(1.5);
    union.update(0.0);
    union.update(-0.0);
    String s = null;
    //null string
    union.update(s);
    s = "";
    //empty string
    union.update(s);
    s = "String";
    //#2 actual string
    union.update(s);
    byte[] byteArr = null;
    //null byte[]
    union.update(byteArr);
    byteArr = new byte[0];
    //empty byte[]
    union.update(byteArr);
    byteArr = "Byte Array".getBytes();
    //#3 actual byte[]
    union.update(byteArr);
    int[] intArr = null;
    //null int[]
    union.update(intArr);
    intArr = new int[0];
    //empty int[]
    union.update(intArr);
    int[] intArr2 = { 1, 2, 3, 4, 5 };
    //#4 actual int[]
    union.update(intArr2);
    long[] longArr = null;
    //null long[]
    union.update(longArr);
    longArr = new long[0];
    //empty long[]
    union.update(longArr);
    long[] longArr2 = { 6, 7, 8, 9 };
    //#5 actual long[]
    union.update(longArr2);
    CompactSketch comp = union.getResult();
    double est = comp.getEstimate();
    boolean empty = comp.isEmpty();
    assertEquals(est, 7.0, 0.0);
    assertFalse(empty);
}

