    assertEquals(extractLgNomLongs(~(v << shift)), 0);
    v = 0XFFL;
    shift = LG_ARR_LONGS_BYTE << 3;
    assertEquals(extractLgArrLongs(v << shift), (int) v);
    assertEquals(extractLgArrLongs(~(v << shift)), 0);
    v = 0XFFL;
